import base64
import hashlib
import json
import shutil
import sqlite3
from datetime import datetime, timezone
from decimal import Decimal
from pathlib import Path

from django.conf import settings
from django.db import connection, transaction
from main.models import Category, Product


def restore_catalog(payload):
    root = Path(settings.BASE_DIR)
    stamp = datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%S%fZ')
    backup_dir = root / 'recovery_backups' / stamp
    backup_dir.mkdir(parents=True, exist_ok=False)
    if connection.vendor == 'sqlite':
        connection.ensure_connection()
        backup = sqlite3.connect(str(backup_dir / 'db.sqlite3'))
        try:
            connection.connection.backup(backup)
        finally:
            backup.close()
    else:
        raise RuntimeError('This recovery script expects the current SQLite database.')

    # Public product images only. No customer data is written into static files.
    assets = root / 'main' / 'static' / 'recovered-catalog'
    assets.mkdir(parents=True, exist_ok=True)
    for name, encoded in payload['images'].items():
        if Path(name).name != name:
            raise ValueError('Invalid asset filename')
        content = base64.b64decode(encoded, validate=True)
        target = assets / name
        if target.exists() and target.read_bytes() != content:
            raise RuntimeError('Refusing to replace a changed recovery image: ' + name)
        target.write_bytes(content)

    template_dir = root / 'main/templates/main'
    catalog = template_dir / 'catalog.html'
    text = catalog.read_text(encoding='utf-8')
    updated = text.replace('{{ product.image.url }}', '{{ product.get_image_url }}')
    # Use the explicit instance namespace from the project's root URLconf.
    updated = updated.replace("'letsplay:", "'main:")
    if text != updated:
        shutil.copy2(catalog, backup_dir / 'catalog.html')
        catalog.write_text(updated, encoding='utf-8')
    detail = template_dir / 'catalog_detail.html'
    text = detail.read_text(encoding='utf-8')
    updated = text.replace("'letsplay:", "'main:")
    if text != updated:
        shutil.copy2(detail, backup_dir / 'catalog_detail.html')
        detail.write_text(updated, encoding='utf-8')

    categories = {'consoles': 'Приставки', 'accessories': 'Аксессуары', 'subscriptions': 'Подписки'}
    created = 0
    skipped = 0
    with transaction.atomic():
        for item in payload['products']:
            # Stable recovery slug makes repeat imports safe and preserves admin edits.
            slug = 'recovered-' + str(item['source_id'])
            if Product.objects.filter(slug=slug).exists():
                skipped += 1
                continue
            category_type = item['category']
            category = Category.objects.filter(category_type=category_type).order_by('pk').first()
            if category is None:
                category = Category.objects.create(name=categories[category_type], slug=category_type, category_type=category_type)
            image = item['asset'] or 'no-photo.svg'
            Product.objects.create(
                name=item['name'], slug=slug, category=category,
                price=Decimal(str(item['archived_price'])), old_price=None,
                image_url='/static/recovered-catalog/' + image,
                description=item['description'], platform=item['platform'],
                subscription_type=item['subscription_type'],
                features=[], specifications=[], is_active=True, in_stock=True,
            )
            created += 1
    print('Created products:', created, '| Existing products preserved:', skipped)
    print('Database backup:', backup_dir / 'db.sqlite3')
    print('Restart the existing container (do not redeploy) to reload templates and static assets.')


restore_catalog(PAYLOAD)
